// Map whichever trigger fired to the Arena jobs it owns.
//
// reviews-run is deliberately ABSENT. Reviews are owned by the grading
// workflow, which claims from the same queue; scheduling both here would put
// two systems on one queue for no gain.
// Every job is idempotent and self-gating: it finds its own work and reports
// `skipped` when there is none, so firing more often than needed is safe and
// firing late is recoverable.
//
// Two cadences are load-bearing rather than cosmetic:
//   email-flush every 15 minutes, because a failed message may only be retried
//     inside the provider's 23h idempotency window and the backoff ladder needs
//     roughly 7.5h of ticks to exhaust its six attempts. A daily flush gave a
//     message ONE attempt before it expired.
//   project-generate hourly through the Sunday window, because six divisions do
//     not fit in one 60s invocation; each tick generates what it has budget for
//     and reports `skipped` for divisions already prepared.
//   jobs-sync every four hours, offset off the hour so it does not collide with
//     the publication tick. Each source carries its own sync interval and the
//     job only picks up the ones that are due, so a more frequent trigger costs
//     nothing and a source can be tuned without touching this workflow.
const byTrigger = {
  'Every 15 minutes': ['email-flush'],
  'Every 4 hours': ['jobs-sync'],
  'Daily 08:00 WIB': ['week-notifications'],
  'Daily 01:30 WIB': ['session-cleanup', 'storage-cleanup'],
  'Sunday hourly 09:00-20:00 WIB': ['project-generate'],
  'Hourly project publication': ['project-drop'],
  // Close then finalize, in that order, every hour. n8n runs the items this
  // node returns through the HTTP node in order, so finalize always sees the
  // weeks close just moved into FINALIZING.
  //
  // This was 'Saturday 00:05' for close and a weekend 2-hourly tick for
  // finalize, which assumed every week ends on the weekly cycle. An ad-hoc week
  // whose deadline fell after Saturday 00:05 -- like ADHOC-2026-09-08-7543,
  // due Saturday 12 September 23:59 WIB -- would not be closed until the
  // following Saturday, six days late, holding back its results and points.
  // Both jobs are self-gating: close only touches OPEN weeks past their
  // deadline, finalize only FINALIZING ones, so an hourly tick that finds
  // nothing reports `skipped` and costs nothing.
  'Hourly week lifecycle': ['week-close', 'week-finalize'],
};

// $prevNode.name is the trigger that started this execution.
const source = $prevNode.name;
const jobs = byTrigger[source];
if (!jobs) throw new Error(`No Arena jobs mapped for trigger "${source}"`);

return jobs.map((job) => ({ json: { job, source } }));

// Surface only what a human would act on. A job reporting `skipped` is the
// normal quiet case and is not an alert.
const out = [];
for (const item of $input.all()) {
  const status = item.json.statusCode;
  const body = item.json.body ?? {};
  const data = body.data ?? {};
  const failed = status !== 200 || data.done === false;
  out.push({
    json: {
      job: data.job ?? 'unknown',
      status,
      ok: !failed,
      detail: data.detail ?? body.error ?? null,
    },
  });
}
return out;
